from hermes_cua_spaces.errors import NotSignedInError, SpaceNotFoundError, UnsupportedSpaceError, explain, CuaSpacesError


def _exc(kind: str, msg: str = "boom"):
    return type(kind, (Exception,), {})(msg)


def test_not_signed_in_says_what_to_run():
    e = explain(_exc("Unauthenticated", "token abc123 rejected"))
    assert isinstance(e, NotSignedInError)
    assert "cua auth login" in str(e)
    assert "abc123" not in str(e)  # never echo what could be a token


def test_not_found_names_the_space_and_next_step():
    e = explain(_exc("NotFound"), space="mybox")
    assert isinstance(e, SpaceNotFoundError)
    assert "'mybox'" in str(e) and "cua spaces ls" in str(e)


def test_capability_missing():
    assert isinstance(explain(_exc("CapabilityMissing", "no shell")), UnsupportedSpaceError)


def test_unknown_kind_still_readable():
    e = explain(_exc("Weird", "first line\nsecond line"), space="x")
    assert "first line" in str(e) and "second line" not in str(e)


def test_passthrough():
    original = CuaSpacesError("already plain")
    assert explain(original) is original

import pytest

from hermes_cua_spaces.config import CREATE, Settings, load_settings, space_name_for


def test_defaults():
    s = load_settings(None, {})
    assert s.creates and s.space == CREATE and s.image == "linux" and s.on == ""


def test_config_values():
    cfg = {"space": "build-box", "on": "local", "image": "linux:24.04", "create_timeout": 30}
    s = load_settings(lambda k, default=None: cfg.get(k, default), {})
    assert (s.space, s.on, s.image, s.create_timeout_s) == ("build-box", "local", "linux:24.04", 30)
    assert not s.creates


def test_env_wins_over_config():
    s = load_settings(lambda k, default=None: "from-config", {"HERMES_CUA_SPACE": "from-env"})
    assert s.space == "from-env"


def test_broken_config_reader_falls_back():
    def boom(*_a, **_k):
        raise RuntimeError("no config")

    assert load_settings(boom, {}).creates


def test_bad_timeout_falls_back():
    s = load_settings(lambda k, default=None: "abc" if k == "create_timeout" else default, {})
    assert s.create_timeout_s == 600


def test_validate_rejects_non_positive_timeout():
    with pytest.raises(ValueError, match="positive"):
        Settings(create_timeout_s=0).validate()


def test_space_name_is_safe_and_stable():
    assert space_name_for("default") == "hermes-default"
    assert space_name_for("Task_ID/42 x") == "hermes-task-id-42-x"
    assert space_name_for("") == "hermes-default"
    assert len(space_name_for("x" * 100)) <= len("hermes-") + 24


def test_delete_on_exit_default_and_overrides():
    assert load_settings(None, {}).delete_on_exit is True
    assert load_settings(lambda k, default=None: False if k == "delete_on_exit" else default, {}).delete_on_exit is False
    assert load_settings(None, {"HERMES_CUA_KEEP": "1"}).delete_on_exit is False


def test_unique_names_differ():
    assert space_name_for("a", unique=True) != space_name_for("a", unique=True)
    assert space_name_for("a", unique=True).startswith("hermes-a-")

import subprocess
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from hermes_cua_spaces.client import ExecResult  # noqa: E402


class LocalShellSpace:
    """A stand-in Space that runs commands in a local temp dir. Mirrors the SDK: `/bin/sh -c <line>`."""

    def __init__(self, root: Path, name: str = "hermes-test"):
        self.id = f"local:{name}"
        self.name = name
        self.root = root
        self.lines: list[str] = []

    def run(self, command: str, timeout_s: float) -> ExecResult:
        self.lines.append(command)
        try:
            p = subprocess.run(
                ["/bin/sh", "-c", command], capture_output=True, timeout=timeout_s, cwd=self.root
            )
        except subprocess.TimeoutExpired as exc:
            return ExecResult((exc.stdout or b"").decode() + "[timeout]", 124)
        return ExecResult((p.stdout + p.stderr).decode(errors="replace"), p.returncode)

    def write(self, path: str, data: bytes) -> None:
        target = Path(path)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)

    def home(self) -> str:
        return str(self.root)


class FakeClient:
    def __init__(self, space: LocalShellSpace):
        self.space = space
        self.calls: list[tuple] = []
        self.deleted: list[str] = []

    def attach(self, space):
        self.calls.append(("attach", space))
        return self.space

    def ensure(self, name, settings):
        self.calls.append(("ensure", name, settings.image, settings.on))
        return self.space, True

    def delete(self, space_id):
        self.deleted.append(space_id)


@pytest.fixture
def space(tmp_path):
    if sys.platform.startswith("win"):
        pytest.skip("this stand-in Space runs /bin/sh; the Windows tests cover Windows")
    return LocalShellSpace(tmp_path)


@pytest.fixture
def client(space):
    return FakeClient(space)

"""Windows Space support, driven against a local PowerShell standing in for the Space.

Needs PowerShell 7 (`pwsh`) on Linux or macOS, or Windows PowerShell on Windows. On a Windows runner
this exercises the real Windows PowerShell 5.1 and Git Bash.
