"""The thin layer between the plugin and the Cua SDK.

Everything the rest of the plugin needs from Cua is the small `SpacesClient` / `SpaceHandle` pair
below, so tests can swap in a fake and the real SDK stays in one file.

Sign-in: the SDK reads the session that `cua auth login` saved. The plugin never reads, stores or
prints a token.
"""

from __future__ import annotations

import inspect
import logging
from dataclasses import dataclass
from typing import Any, Optional, Protocol

from ._loop import run_sync
from .config import Settings
from .errors import (
    CuaSpacesError,
    SpaceCreateError,
    SpaceNotFoundError,
    explain,
)

logger = logging.getLogger(__name__)

# Seconds of slack on top of a command's own timeout for the round trip to the Space.
_RPC_SLACK_S = 15.0


@dataclass(frozen=True)
class ExecResult:
    output: str
    exit_code: int


class SpaceHandle(Protocol):
    id: str
    name: str
    os: str  # "linux", "macos" or "windows" ("" when the Space did not say)

    def run(self, command: str, timeout_s: float) -> ExecResult: ...

    def write(self, path: str, data: bytes) -> None: ...

    def home(self) -> str: ...


class SpacesClient(Protocol):
    def attach(self, space: str) -> SpaceHandle:
        """Connect to an existing Space by name or id, starting it if it is stopped."""

    def ensure(self, name: str, settings: Settings) -> tuple[SpaceHandle, bool]:
        """Reuse the Space called `name` if it exists, otherwise create it. Returns (handle, created)."""

    def delete(self, space_id: str) -> None: ...


def _exec_result(res: Any) -> ExecResult:
    """Map the SDK's bash result to (merged output, exit code) the way Hermes expects."""
    parts = [res.stdout or ""]
    if res.stderr:
        parts.append(res.stderr)
    if res.error:
        parts.append(f"[Space error: {res.error}]\n")
    output = "".join(parts)
    if res.timed_out:
        return ExecResult(output, 124)
    if res.exit_code is not None:
        return ExecResult(output, int(res.exit_code))
    if res.signal:
        return ExecResult(output, 137 if "KILL" in str(res.signal) else 143)
    return ExecResult(output, 1)


class _SdkSpace:
    def __init__(self, space: Any, info: Any):
        self._space = space
        self.id: str = info.id
        self.name: str = info.name
        self.os: str = (getattr(info, "os", "") or "").lower()

    def run(self, command: str, timeout_s: float) -> ExecResult:
        timeout_ms = max(1, int(timeout_s * 1000))
        try:
            res = run_sync(self._space.bash(command, timeout_ms), timeout_s + _RPC_SLACK_S)
        except TimeoutError:
            return ExecResult(f"[Command timed out after {int(timeout_s)}s]\n", 124)
        except Exception as exc:
            raise explain(exc, space=self.name) from exc
        return _exec_result(res)

    def write(self, path: str, data: bytes) -> None:
        try:
            run_sync(self._space.write(path, data), 120)
        except Exception as exc:
            raise explain(exc, space=self.name) from exc

    def home(self) -> str:
        try:
            return str(run_sync(self._space.home(), 60))
        except Exception as exc:
            raise explain(exc, space=self.name) from exc


class SdkSpacesClient:
    """Talks to Cua through the `cua` Python package."""

    def __init__(self) -> None:
        try:
            import cua
        except ImportError as exc:
            raise CuaSpacesError(
                "The `cua` Python package is not installed. Run `hermes pm repair`, "
                "or `pip install 'cua>=0.5.0,<0.6'` in the Hermes environment."
            ) from exc
        self._cua = cua
        # Same topology as the `cua` command: the running `cua daemon` (so Spaces and your cua.ai
        # sign-in are shared with the CLI and the app), else a runtime inside this process.
        self._runtime = cua.Cua.auto(cua.CuaConfig(**self._session_kwargs(cua)))
        self._spaces = self._runtime.spaces()

    @staticmethod
    def _session_kwargs(cua: Any) -> dict[str, bool]:
        """Ask the SDK to use the `cua auth login` session. The flag was renamed between releases."""
        params = inspect.signature(cua.CuaConfig.__init__).parameters
        for flag in ("account_from_session", "fleet_from_session"):
            if flag in params:
                return {flag: True}
        return {}

    def _handle(self, info: Any) -> SpaceHandle:
        try:
            space = run_sync(self._spaces.space(info.id), 60)
        except Exception as exc:
            raise explain(exc, space=info.name) from exc
        return _SdkSpace(space, info)

    def _resolve(self, space: str) -> Any:
        try:
            return run_sync(self._spaces.resolve(space), 60)
        except Exception as exc:
            raise explain(exc, space=space) from exc

    def _ensure_running(self, info: Any) -> Any:
        state = (getattr(info, "power_state", "") or getattr(info, "power", "") or "").lower()
        if state in ("stopped", "suspended", "off", "paused"):
            logger.info("Starting Space %s (it was %s)", info.name, state)
            try:
                run_sync(self._spaces.start(info.id), 600)
            except Exception as exc:
                raise explain(exc, space=info.name) from exc
            info = self._resolve(info.id)
        return info

    def attach(self, space: str) -> SpaceHandle:
        info = self._ensure_running(self._resolve(space))
        return self._handle(info)

    def ensure(self, name: str, settings: Settings) -> tuple[SpaceHandle, bool]:
        try:
            return self.attach(name), False
        except SpaceNotFoundError:
            pass
        options = self._cua.SpaceCreateOptions(
            image=settings.image or None,
            on=settings.on or None,
            name=name,
            wait=True,
            timeout_ms=settings.create_timeout_s * 1000,
        )
        logger.info("Creating Space %s (image=%s, on=%s)", name, settings.image, settings.on or "default")
        try:
            result = run_sync(self._spaces.create(options), settings.create_timeout_s + 60)
        except Exception as exc:
            raise explain(exc, space=name) from exc
        if result.space is None:
            raise SpaceCreateError(
                f"The Space '{name}' is still being created. Wait for it to finish "
                "(`cua spaces ls`), then start Hermes again."
            )
        return self._handle(result.space), True

    def delete(self, space_id: str) -> None:
        try:
            run_sync(self._spaces.delete(space_id), 300)
        except Exception as exc:
            raise explain(exc, space=space_id) from exc

"""Errors, in plain words. Every message says what happened and what to do next."""

from __future__ import annotations


class CuaSpacesError(RuntimeError):
    """Something went wrong talking to Cua. The message is safe to show to the user."""


class NotSignedInError(CuaSpacesError):
    pass


class SpaceNotFoundError(CuaSpacesError):
    pass


class SpaceCreateError(CuaSpacesError):
    pass


class UnsupportedSpaceError(CuaSpacesError):
    pass


def explain(exc: BaseException, *, space: str = "") -> CuaSpacesError:
    """Turn an error from the Cua SDK into a CuaSpacesError with a next step.

    The SDK raises `CuaError.<Kind>` classes. We go by the kind name so this keeps working when the
    message wording changes, and we never echo anything that could hold a token.
    """
    if isinstance(exc, CuaSpacesError):
        return exc
    kind = type(exc).__name__
    detail = str(exc).strip().splitlines()[0] if str(exc).strip() else kind
    where = f" '{space}'" if space else ""
    if kind in ("Unauthenticated", "PermissionDenied"):
        return NotSignedInError(
            "Cua did not accept your sign-in. Run `cua auth login` in a terminal, then try again."
        )
    if kind == "NotFound":
        return SpaceNotFoundError(
            f"Cua can't find the Space{where}. Run `cua spaces ls` to see your Spaces, "
            "or set the Space to `create` to make a new one."
        )
    if kind in ("AmbiguousSandbox",):
        return SpaceNotFoundError(
            f"More than one Space is called{where}. Use its full id from `cua spaces ls`, "
            "for example `local:name`."
        )
    if kind in ("InvalidPlacement", "InvalidArgument"):
        return SpaceCreateError(
            f"Cua rejected the Space settings: {detail}. Check `on` and `image` in the plugin settings."
        )
    if kind in ("InsufficientDisk",):
        return SpaceCreateError(f"There is not enough free disk space to create a Space: {detail}")
    if kind in ("ProviderNotConfigured", "DaemonNotRunning", "Runtime"):
        return SpaceCreateError(
            f"Cua can't start a Space here yet: {detail}. Run `cua doctor` to see what is missing."
        )
    if kind in ("Timeout",):
        return SpaceCreateError(
            f"The Space{where} took too long to answer. It may still be starting; try again in a minute."
        )
    if kind in ("Transport", "Http", "Closed", "Env"):
        return CuaSpacesError(
            f"Could not reach the Space{where}: {detail}. Check it is running with `cua spaces ls`."
        )
    if kind == "Cloud":
        return SpaceCreateError(f"Cua Cloud said: {detail}. Use `on: local`, or a machine of your own.")
    if kind == "CapabilityMissing" or kind == "SpacesdNotAvailable":
        return UnsupportedSpaceError(
            f"The Space{where} can't run commands for Hermes ({detail}). "
            "Use a Cua Spaces image such as `linux`."
        )
    return CuaSpacesError(f"Cua error{(' for Space' + where) if where else ''}: {detail}")

"""Windows Space support: the PowerShell and bash scripts Hermes commands are wrapped in.

Hermes writes its terminal tools for a POSIX shell. A Windows Space has none, so the plugin:

* runs the `terminal` tool's commands in PowerShell (`pwsh` if the Space has it, else the
  `powershell.exe` every Windows has),
* runs the commands Hermes builds for its other tools (file search, background processes, code
  execution) in Git Bash when the Space has Git for Windows, and otherwise says in plain words
  that this tool needs it,
* keeps the file read/write tools off the shell entirely (see `windows_files.py`).

Every script is staged as a file in the Space and started with a short command line. That keeps
quoting, the Windows 8,191-character command limit and the console code page out of the way:
the command text travels as base64, and output leaves as UTF-8 bytes.
"""

from __future__ import annotations

import base64
import re
import shlex
from dataclasses import dataclass

# What the plugin tells the model and the user about a Windows Space.
TERMINAL_NOTE = "On this Windows machine the terminal tool runs PowerShell, not bash."

NO_BASH_MESSAGE = (
    "This Hermes tool runs Unix shell commands, and this Windows Space has no Unix shell (bash). "
    "The terminal tool still works here, in PowerShell, and so do reading, writing and patching files. "
    "To use this tool too, install Git for Windows in the Space (in its PowerShell: "
    "`winget install --id Git.Git -e`), then try again."
)

# Windows PowerShell 5.1 and PowerShell 7 both run these options.
_PS_FLAGS = "-NoProfile -NonInteractive -ExecutionPolicy Bypass"

_DRIVE = re.compile(r"^[A-Za-z]:[\\/]")


def b64(text: str) -> str:
    return base64.b64encode(text.encode("utf-8")).decode("ascii")


def ps_quote(text: str) -> str:
    """A PowerShell single-quoted string literal."""
    return "'" + text.replace("'", "''") + "'"


def encoded_command(script: str) -> str:
    """`-EncodedCommand` payload: base64 of the script as UTF-16LE."""
    return base64.b64encode(script.encode("utf-16-le")).decode("ascii")


def to_forward(path: str) -> str:
    """`C:\\Users\\me` -> `C:/Users/me`. Every Windows API, PowerShell and Git Bash accept it."""
    return path.replace("\\", "/")


def looks_like_windows_path(path: str) -> bool:
    return bool(_DRIVE.match(path)) or path.startswith("\\\\")


@dataclass(frozen=True)
class WindowsInfo:
    """What the first probe learned about the Space."""

    shell: str  # "pwsh" or "powershell.exe"
    home: str  # the user profile folder, e.g. C:\Users\cua
    temp: str  # temp folder with forward slashes
    bash: str  # Git Bash, or "" when the Space has none
    user: str = ""


_PROBE = r"""
$ErrorActionPreference = 'SilentlyContinue'
$pw = Get-Command pwsh | Select-Object -First 1
$sh = 'powershell.exe'
if ($pw) { $sh = 'pwsh' }
$home_ = [Environment]::GetFolderPath('UserProfile')
$tmp = [IO.Path]::GetTempPath().TrimEnd('\', '/')
$roots = @($env:ProgramFiles, ${env:ProgramFiles(x86)}, (Join-Path $env:LOCALAPPDATA 'Programs')) | Where-Object { $_ }
$bash = ''
foreach ($r in $roots) {
  $c = Join-Path $r 'Git\bin\bash.exe'
  if (Test-Path -LiteralPath $c) { $bash = $c; break }
}
Write-Output "hermes-cua-shell=$sh"
Write-Output "hermes-cua-home=$home_"
Write-Output "hermes-cua-temp=$tmp"
Write-Output "hermes-cua-bash=$bash"
Write-Output "hermes-cua-user=$([Environment]::UserName)"
"""


def probe_line() -> str:
    """The command line that asks the Space about itself. Always `powershell.exe`: it is on every Windows."""
    return f"powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand {encoded_command(_PROBE)}"


def parse_probe(output: str) -> WindowsInfo | None:
    found: dict[str, str] = {}
    for line in output.splitlines():
        line = line.strip()
        if line.startswith("hermes-cua-") and "=" in line:
            key, _, value = line[len("hermes-cua-"):].partition("=")
            found[key] = value.strip()
    if not found.get("home") or not found.get("shell"):
        return None
    return WindowsInfo(
        shell=found["shell"],
        home=found["home"],
        temp=to_forward(found.get("temp") or found["home"]),
        bash=found.get("bash", ""),
        user=found.get("user", ""),
    )


def script_path(info: WindowsInfo, run_id: str, ext: str) -> str:
    """Where a staged script lives. The run id is in the name so a stuck command can be found and stopped."""
    return f"{info.temp}/hermes-cua-run-{run_id}.{ext}"


# -- PowerShell: the terminal tool --

_PS_WRAPPER = r"""
$ErrorActionPreference = 'Continue'
$ProgressPreference = 'SilentlyContinue'
$__enc = New-Object System.Text.UTF8Encoding($false)
try { [Console]::OutputEncoding = $__enc } catch {}
try { [Console]::InputEncoding = $__enc } catch {}
$OutputEncoding = $__enc
$env:PYTHONUTF8 = '1'
$env:PYTHONIOENCODING = 'utf-8'
if (-not $env:AI_AGENT) { $env:AI_AGENT = 'hermes-agent' }
if (-not $env:HERMES_AGENT) { $env:HERMES_AGENT = 'true' }
$__stdout = [Console]::OpenStandardOutput()
function __hw([string]$s) { $b = $__enc.GetBytes($s); $__stdout.Write($b, 0, $b.Length); $__stdout.Flush() }
function __b64([string]$s) { $__enc.GetString([Convert]::FromBase64String($s)) }
$__cwd = __b64 '@CWD@'
$__cmd = __b64 '@CMD@'
$__ec = 0
try {
  $__cdok = $true
  try { Set-Location -LiteralPath $__cwd -ErrorAction Stop } catch {
    $__cdok = $false
    __hw ("hermes: the working folder '" + $__cwd + "' does not exist in this Space.`n")
    $__ec = 126
  }
  if ($__cdok) {
@STDIN@    $global:LASTEXITCODE = $null
    $global:__ok = $true
    $global:__code = $null
    try {
      $__sb = [scriptblock]::Create($__cmd + "`n`$global:__ok = `$?`n`$global:__code = `$global:LASTEXITCODE")
      & $__sb *>&1 | ForEach-Object {
        if ($_ -is [System.Management.Automation.ErrorRecord]) {
          if ($_.FullyQualifiedErrorId -eq 'NativeCommandError' -or $_.CategoryInfo.Category -eq 'NotSpecified') { $_.Exception.Message }
          else { ($_ | Out-String).TrimEnd() }
        } else { $_ }
      } | Out-String -Stream -Width 4096 | ForEach-Object { __hw ($_ + "`n") }
    } catch {
      __hw (($_ | Out-String).TrimEnd() + "`n")
      $global:__ok = $false
      $global:__code = 1
    }
    if (-not $global:__ok) {
      if (($global:__code -is [int]) -and ($global:__code -ne 0)) { $__ec = $global:__code } else { $__ec = 1 }
    }
  }
} finally {
  $__here = (Get-Location -PSProvider FileSystem).ProviderPath
  __hw ("`n@MARKER@" + $__here + "@MARKER@`n")
  Remove-Item -LiteralPath $PSCommandPath -Force -ErrorAction SilentlyContinue
}
exit $__ec
"""


def build_powershell_script(command: str, cwd: str, marker: str, stdin_path: str = "") -> str:
    """The script file for one terminal command. Ends by printing the working folder between `marker`s."""
    stdin = ""
    if stdin_path:
        # Feed the staged text to the command's input, then delete it.
        stdin = (
            f"    $__in = [IO.File]::ReadAllText({ps_quote(stdin_path)}, $__enc)\n"
            f"    Remove-Item -LiteralPath {ps_quote(stdin_path)} -Force -ErrorAction SilentlyContinue\n"
        )
        command = f"$__in | & {{\n{command}\n}}"
    return (
        _PS_WRAPPER.replace("@CWD@", b64(cwd))
        .replace("@CMD@", b64(command))
        .replace("@MARKER@", marker)
        .replace("@STDIN@", stdin)
        .lstrip("\n")
    )


def powershell_line(info: WindowsInfo, path: str) -> str:
    return f'{info.shell} {_PS_FLAGS} -File "{path}"'


# -- Git Bash: the commands Hermes builds for its other tools --

_BASH_LAUNCHER = r"""
$ErrorActionPreference = 'Stop'
$p = New-Object System.Diagnostics.Process
$p.StartInfo.FileName = @BASH@
$p.StartInfo.Arguments = '-l "' + @SCRIPT@ + '"'
$p.StartInfo.UseShellExecute = $false
$p.StartInfo.RedirectStandardOutput = $true
$p.StartInfo.CreateNoWindow = $true
[void]$p.Start()
$out = [Console]::OpenStandardOutput()
$p.StandardOutput.BaseStream.CopyTo($out)
$out.Flush()
$p.WaitForExit()
Remove-Item -LiteralPath $PSCommandPath -Force -ErrorAction SilentlyContinue
exit $p.ExitCode
"""


def build_bash_script(command: str, cwd: str, marker: str) -> str:
    """A bash script (LF endings) that runs `command` in `cwd` and prints the folder between `marker`s.

    `pwd -W` gives the Windows form of the folder (`C:/Users/me`), so the next command, which may
    run in PowerShell, can use it.
    """
    return (
        "exec 2>&1\n"
        "trap 'rm -f -- \"$0\"' EXIT\n"
        'export AI_AGENT="${AI_AGENT:-hermes-agent}" HERMES_AGENT="${HERMES_AGENT:-true}"\n'
        f"builtin cd -- {shlex.quote(to_forward(cwd))} || exit 126\n"
        f"eval {shlex.quote(command)}\n"
        "__hermes_ec=$?\n"
        f"printf '\\n{marker}%s{marker}\\n' \"$(pwd -W 2>/dev/null || pwd -P)\"\n"
        "exit $__hermes_ec\n"
    )


def build_bash_launcher(info: WindowsInfo, bash_script_path: str) -> str:
    """A tiny PowerShell file that starts Git Bash and copies its output through byte for byte.

    Going through PowerShell's own output would turn every LF into CRLF and so corrupt file reads.
    """
    return (
        _BASH_LAUNCHER.replace("@BASH@", ps_quote(info.bash))
        .replace("@SCRIPT@", ps_quote(bash_script_path))
        .lstrip("\n")
    )


def cancel_line(info: WindowsInfo, run_id: str) -> str:
    """Stop a command (and its children) by the run id in its script name, and remove its leftovers."""
    script = (
        "$ErrorActionPreference = 'SilentlyContinue'\n"
        f"$needle = {ps_quote('*hermes-cua-run-' + run_id + '*')}\n"
        "Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like $needle -and $_.ProcessId -ne $PID } |\n"
        "  ForEach-Object { & taskkill.exe /T /F /PID $_.ProcessId | Out-Null }\n"
        f"Remove-Item -Path {ps_quote(info.temp + '/hermes-cua-run-' + run_id + '.*')} -Force\n"
    )
    return f"{info.shell} {_PS_FLAGS} -EncodedCommand {encoded_command(script)}"

"""File read, write, patch, delete and move for a Windows Space, without a Unix shell.

Hermes's file tools build `cat`, `sed`, `wc` and `mv` commands. A Windows Space has none of them, so
for a Windows Space only, `install()` swaps those tools' methods for ones that work on Windows paths:
bytes travel as base64 through PowerShell, and files are written with the Cua SDK. Linux and macOS
Spaces, and every other Hermes backend, keep Hermes's own code: each replacement checks the
environment first and hands anything else straight back to the original method.

`search` and the other Unix-shell tools are not replaced here: they need Git Bash in the Space
(see `windows.py`), and say so in plain words when it is missing.
"""

from __future__ import annotations

import base64
import dataclasses
import functools
import hashlib
import logging
import ntpath
import os
import posixpath
import uuid
from typing import Any, Optional

from . import windows as win

logger = logging.getLogger(__name__)

_MAX_READ_BYTES = 25 * 1024 * 1024
_HEAD_BYTES = 4096
_BOM = "﻿"

_PS_STAT = r"""
$ErrorActionPreference = 'Stop'
$p = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('@PATH@'))
if (Test-Path -LiteralPath $p -PathType Container) { Write-Output 'dir'; exit 0 }
if (-not (Test-Path -LiteralPath $p -PathType Leaf)) { Write-Output 'missing'; exit 0 }
$item = Get-Item -LiteralPath $p
$fs = [IO.File]::Open($p, 'Open', 'Read', 'ReadWrite')
try {
  $buf = New-Object byte[] @HEAD@
  $n = $fs.Read($buf, 0, $buf.Length)
} finally { $fs.Dispose() }
$head = [Convert]::ToBase64String($buf, 0, $n)
Write-Output ('file ' + $item.Length + ' ' + $head)
"""

_PS_READ = r"""
$ErrorActionPreference = 'Stop'
$p = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('@PATH@'))
$fs = [IO.File]::Open($p, 'Open', 'Read', 'ReadWrite')
try {
  $ms = New-Object IO.MemoryStream
  $fs.CopyTo($ms)
} finally { $fs.Dispose() }
Write-Output ([Convert]::ToBase64String($ms.ToArray()))
"""

_PS_WRITE = r"""
$ErrorActionPreference = 'Stop'
$dst = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('@DST@'))
$tmp = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('@TMP@'))
$dir = Split-Path -Parent $dst
if ($dir -and -not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Force -Path $dir) }
Move-Item -LiteralPath $tmp -Destination $dst -Force
Write-Output ('sha256 ' + (Get-FileHash -LiteralPath $dst -Algorithm SHA256).Hash.ToLower())
"""

_PS_DELETE = r"""
$ErrorActionPreference = 'Stop'
$p = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('@PATH@'))
if (Test-Path -LiteralPath $p -PathType Container) {
  if ('@RECURSIVE@' -eq '1') { Remove-Item -LiteralPath $p -Recurse -Force }
  else { Write-Output 'is-a-directory'; exit 2 }
} elseif (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Force }
Write-Output 'ok'
"""

_PS_MOVE = r"""
$ErrorActionPreference = 'Stop'
$src = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('@SRC@'))
$dst = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('@DST@'))
$dir = Split-Path -Parent $dst
if ($dir -and -not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Force -Path $dir) }
Move-Item -LiteralPath $src -Destination $dst -Force
Write-Output 'ok'
"""


class WindowsFiles:
    """File operations on one Windows Space's environment."""

    def __init__(self, env: Any) -> None:
        self._env = env

    # -- paths --
    def resolve(self, path: str) -> str:
        """Turn what the model gave into a full Windows path: expand `~`, anchor a relative path at the
        terminal's working folder, and tidy `.` and `..`."""
        info = self._env.windows_info
        # `ntpath` for a real Windows Space. A Space whose profile folder is not a Windows path (only
        # the plugin's own tests, on Linux or macOS) uses `posixpath`.
        flavor = ntpath if win.looks_like_windows_path(info.home) else posixpath
        path = path.strip()
        if path == "~" or path.startswith(("~/", "~\\")):
            path = info.home + path[1:]
        if not (win.looks_like_windows_path(path) or (flavor is posixpath and path.startswith("/"))):
            path = flavor.join(self._env.cwd or info.home, path)
        return flavor.normpath(path)

    # -- primitives (each is one PowerShell call) --
    def _ps(self, template: str, **fields: str) -> tuple[str, int]:
        script = template
        for key, value in fields.items():
            script = script.replace(f"@{key}@", value)
        result = self._env.run_powershell(script, timeout=120)
        return result.output.strip(), result.exit_code

    def stat(self, path: str) -> tuple[str, int, bytes]:
        """("missing" | "dir" | "file", size, first bytes)."""
        out, code = self._ps(_PS_STAT, PATH=win.b64(path), HEAD=str(_HEAD_BYTES))
        if code != 0:
            raise OSError(out or "could not look at the file")
        if out == "missing" or out == "dir":
            return out, 0, b""
        _, size, head = (out.split(" ", 2) + ["", ""])[:3]
        return "file", int(size or 0), base64.b64decode(head or "")

    def read_bytes(self, path: str) -> bytes:
        out, code = self._ps(_PS_READ, PATH=win.b64(path))
        if code != 0:
            raise OSError(out or "could not read the file")
        return base64.b64decode("".join(out.split()))

    def write_bytes(self, path: str, data: bytes) -> str:
        """Write `data` to `path`, creating folders. Returns the SHA-256 of what landed on disk."""
        tmp = f"{self._env.windows_info.temp}/hermes-cua-file-{uuid.uuid4().hex[:16]}.tmp"
        self._env._call(lambda sp: sp.write(tmp, data))
        out, code = self._ps(_PS_WRITE, DST=win.b64(path), TMP=win.b64(tmp))
        if code != 0 or not out.startswith("sha256 "):
            raise OSError(out or "could not write the file")
        return out.split(" ", 1)[1].strip()

    def delete(self, path: str, recursive: bool) -> None:
        out, code = self._ps(_PS_DELETE, PATH=win.b64(path), RECURSIVE="1" if recursive else "0")
        if code == 2:
            raise OSError(f"{path} is a folder")
        if code != 0:
            raise OSError(out or "could not delete")

    def move(self, src: str, dst: str) -> None:
        out, code = self._ps(_PS_MOVE, SRC=win.b64(src), DST=win.b64(dst))
        if code != 0:
            raise OSError(out or "could not move")


# -- the replacement tool methods (they receive Hermes's ShellFileOperations as `fo`) --


def _fo_module():
    from tools import file_operations

    return file_operations


def _make(cls: Any, **fields: Any) -> Any:
    """Build one of Hermes's result objects with the fields this Hermes version has."""
    names = {f.name for f in dataclasses.fields(cls)} if dataclasses.is_dataclass(cls) else set()
    return cls(**{k: v for k, v in fields.items() if not names or k in names})


def _strip_bom(text: str) -> tuple[str, bool]:
    return (text[1:], True) if text.startswith(_BOM) else (text, False)


def _is_image(fo: Any, path: str) -> bool:
    try:
        return bool(fo._is_image(path))
    except Exception:
        return os.path.splitext(path)[1].lower() in (".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp", ".ico")


def _probably_binary(fo: Any, path: str, head: bytes) -> bool:
    mod = _fo_module()
    if os.path.splitext(path)[1].lower() in getattr(mod, "BINARY_EXTENSIONS", ()):
        return True
    check = getattr(fo, "_is_likely_binary_bytes", None)
    return bool(check(head)) if check else (b"\x00" in head)


def _read_text_file(files: WindowsFiles, fo: Any, path: str):
    """Common start of every read: (resolved path, size, head, error result or None)."""
    mod = _fo_module()
    rpath = files.resolve(path)
    try:
        kind, size, head = files.stat(rpath)
    except OSError as exc:
        return rpath, 0, b"", _make(mod.ReadResult, error=f"Could not read {rpath}: {exc}")
    if kind == "missing":
        return rpath, 0, b"", _make(mod.ReadResult, error=f"File not found: {rpath}", not_found=True)
    if kind == "dir":
        return rpath, 0, b"", _make(mod.ReadResult, error=f"{rpath} is a folder, not a file. List it with the terminal tool: Get-ChildItem.")
    if size > _MAX_READ_BYTES:
        return rpath, size, head, _make(
            mod.ReadResult,
            file_size=size,
            error=f"{rpath} is too large to read this way ({size:,} bytes). Use the terminal tool, for example Get-Content -TotalCount 200.",
        )
    return rpath, size, head, None


def read_file(files: WindowsFiles, fo: Any, path: str, offset: int = 1, limit: int = 2000):
    mod = _fo_module()
    rpath, size, head, error = _read_text_file(files, fo, path)
    if error is not None:
        return error
    normalize = getattr(mod, "normalize_read_pagination", None)
    if normalize:
        offset, limit = normalize(offset, limit)
    if _is_image(fo, rpath):
        return _make(
            mod.ReadResult,
            is_image=True,
            is_binary=True,
            file_size=size,
            hint="Image file detected. Use vision_analyze with this file path to inspect the image contents.",
        )
    if _probably_binary(fo, rpath, head):
        describe = getattr(mod, "describe_binary_file", None)
        return _make(
            mod.ReadResult,
            is_binary=True,
            file_size=size,
            error=describe(head, size) if describe else f"{rpath} is a binary file.",
        )
    if size == 0:
        return _make(mod.ReadResult, content="", total_lines=0, file_size=0, hint="File is empty (0 bytes).")
    try:
        data = files.read_bytes(rpath)
    except OSError as exc:
        return _make(mod.ReadResult, error=f"Failed to read file: {exc}")
    text, _ = _strip_bom(data.decode("utf-8", "replace"))
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    total = len(lines)
    end = offset + limit - 1
    page = lines[offset - 1 : end]
    truncated = total > end
    hint = f"Use offset={end + 1} to continue reading (showing {offset}-{end} of {total} lines)" if truncated else None
    if offset > total > 0:
        return _make(
            mod.ReadResult,
            content="",
            total_lines=total,
            file_size=size,
            hint=f"Note: offset {offset} is beyond the end of the file ({total} lines total). Retry with offset <= {total}.",
        )
    return _make(
        mod.ReadResult,
        content=fo._add_line_numbers("\n".join(page), offset),
        total_lines=total,
        file_size=size,
        truncated=truncated,
        hint=hint,
    )


def read_file_raw(files: WindowsFiles, fo: Any, path: str):
    mod = _fo_module()
    rpath, size, head, error = _read_text_file(files, fo, path)
    if error is not None:
        return error
    if _is_image(fo, rpath):
        return _make(mod.ReadResult, is_image=True, is_binary=True, file_size=size)
    if _probably_binary(fo, rpath, head):
        return _make(mod.ReadResult, is_binary=True, file_size=size, error=f"{rpath} is a binary file.")
    try:
        data = files.read_bytes(rpath)
    except OSError as exc:
        return _make(mod.ReadResult, error=f"Failed to read file: {exc}")
    content, _ = _strip_bom(data.decode("utf-8", "surrogateescape"))
    result = _make(mod.ReadResult, content=content, file_size=size)
    _set_sha(result, data)
    return result


def read_file_bytes(files: WindowsFiles, fo: Any, path: str, max_bytes: Optional[int] = None):
    mod = _fo_module()
    rpath, size, _head, error = _read_text_file(files, fo, path)
    if error is not None:
        return error
    if max_bytes is not None and size > max_bytes:
        return _make(mod.ReadResult, file_size=size, error=f"File is too large ({size:,} bytes, limit is {max_bytes:,})")
    try:
        data = files.read_bytes(rpath)
    except OSError as exc:
        return _make(mod.ReadResult, error=f"Failed to read binary file: {exc}")
    return _make(mod.ReadResult, base64_content=base64.b64encode(data).decode("ascii"), file_size=size, is_binary=True)


def _set_sha(result: Any, data: bytes) -> None:
    try:
        result._content_sha256 = hashlib.sha256(data).hexdigest()
    except Exception:
        pass


def write_file(files: WindowsFiles, fo: Any, path: str, content: str, pre_content: Optional[str] = None):
    mod = _fo_module()
    rpath = files.resolve(path)
    try:
        encoded = content.encode("utf-8", "surrogateescape")
    except UnicodeEncodeError:
        return _make(mod.WriteResult, error="The content has characters that cannot be saved as UTF-8 text.")
    # Keep a file's line endings and byte-order mark the way Hermes does: read_file hides both.
    try:
        kind, _size, head = files.stat(rpath)
    except OSError as exc:
        return _make(mod.WriteResult, error=f"Failed to write file: {exc}")
    if kind == "dir":
        return _make(mod.WriteResult, error=f"{rpath} is a folder, not a file.")
    if kind == "file":
        if b"\r\n" in head and "\r\n" not in content:
            content = content.replace("\r\n", "\n").replace("\n", "\r\n")
        if head.startswith(b"\xef\xbb\xbf") and not content.startswith(_BOM):
            content = _BOM + content
        encoded = content.encode("utf-8", "surrogateescape")
    try:
        digest = files.write_bytes(rpath, encoded)
    except OSError as exc:
        return _make(mod.WriteResult, error=f"Failed to write file: {exc}")
    verified = digest == hashlib.sha256(encoded).hexdigest()
    if not verified:
        return _make(mod.WriteResult, error=f"Wrote {rpath}, but what is on disk differs from what was sent. Try again.")
    result = _make(mod.WriteResult, bytes_written=len(encoded), dirs_created=True, verified=True)
    _set_sha(result, encoded)
    return result


def patch_replace(files: WindowsFiles, fo: Any, path: str, old_string: str, new_string: str, replace_all: bool = False):
    mod = _fo_module()
    rpath = files.resolve(path)
    try:
        kind, _size, _head = files.stat(rpath)
        if kind != "file":
            return _make(mod.PatchResult, error=f"File not found: {rpath}" if kind == "missing" else f"{rpath} is a folder.")
        data = files.read_bytes(rpath)
    except OSError as exc:
        return _make(mod.PatchResult, error=f"Failed to read file: {exc}")
    raw = data.decode("utf-8", "surrogateescape")
    content, _ = _strip_bom(raw)

    from tools import fuzzy_match

    notes: list = []
    try:
        new_content, count, strategy, error = fuzzy_match.fuzzy_find_and_replace(
            content, old_string, new_string, replace_all, correction_notes=notes
        )
    except TypeError:  # an older Hermes without correction notes
        new_content, count, strategy, error = fuzzy_match.fuzzy_find_and_replace(
            content, old_string, new_string, replace_all
        )
    if error or count == 0:
        return _make(mod.PatchResult, error=error or f"Could not find match for old_string in {rpath}")
    if "\r\n" in content:
        new_content = new_content.replace("\r\n", "\n").replace("\n", "\r\n")
    written = fo.write_file(rpath, new_content, pre_content=raw) if _accepts_pre_content(fo) else fo.write_file(rpath, new_content)
    if getattr(written, "error", None):
        return _make(mod.PatchResult, error=f"Failed to write changes: {written.error}")
    return _make(
        mod.PatchResult,
        success=True,
        diff=fo._unified_diff(content, new_content, rpath),
        files_modified=[rpath],
        note="\n".join(str(n) for n in notes if n) or None,
    )


def _accepts_pre_content(fo: Any) -> bool:
    import inspect

    try:
        return "pre_content" in inspect.signature(fo.write_file).parameters
    except (TypeError, ValueError):
        return False


def delete_file(files: WindowsFiles, fo: Any, path: str):
    return _delete(files, path, recursive=False)


def delete_path(files: WindowsFiles, fo: Any, path: str, recursive: bool = False):
    return _delete(files, path, recursive=recursive)


def _delete(files: WindowsFiles, path: str, recursive: bool):
    mod = _fo_module()
    rpath = files.resolve(path)
    try:
        files.delete(rpath, recursive)
    except OSError as exc:
        return _make(mod.WriteResult, error=f"Failed to delete {rpath}: {exc}")
    return _make(mod.WriteResult)


def move_file(files: WindowsFiles, fo: Any, src: str, dst: str):
    mod = _fo_module()
    rsrc, rdst = files.resolve(src), files.resolve(dst)
    try:
        files.move(rsrc, rdst)
    except OSError as exc:
        return _make(mod.WriteResult, error=f"Failed to move {rsrc} -> {rdst}: {exc}")
    return _make(mod.WriteResult)


def search(files: WindowsFiles, fo: Any, *args: Any, **kwargs: Any):
    """Search runs `rg`/`grep`/`find`. Use them through Git Bash if the Space has it, else say so."""
    if files._env.windows_info.bash:
        return fo._hermes_cua_original_search(*args, **kwargs)
    return _make(_fo_module().SearchResult, error=win.NO_BASH_MESSAGE)


_REPLACEMENTS = {
    "read_file": read_file,
    "read_file_raw": read_file_raw,
    "read_file_bytes": read_file_bytes,
    "write_file": write_file,
    "patch_replace": patch_replace,
    "delete_file": delete_file,
    "delete_path": delete_path,
    "move_file": move_file,
}


def _files_for(fo: Any) -> Optional[WindowsFiles]:
    env = getattr(fo, "env", None)
    try:
        return env.windows_files if getattr(env, "is_windows", False) else None
    except Exception:
        return None


def _wrap(cls: Any, name: str, native: Any) -> None:
    original = getattr(cls, name, None)
    if original is None or getattr(original, "_hermes_cua_wrapped", False):
        return

    @functools.wraps(original)
    def method(self, *args: Any, **kwargs: Any):
        files = _files_for(self)
        if files is None:
            return original(self, *args, **kwargs)
        if name == "search":
            self._hermes_cua_original_search = functools.partial(original, self)
        return native(files, self, *args, **kwargs)

    method._hermes_cua_wrapped = True  # type: ignore[attr-defined]
    setattr(cls, name, method)


def install() -> bool:
    """Teach Hermes's file tools about Windows Spaces. Safe to call more than once; returns False when
    this Hermes has no file tools to change."""
    try:
        from tools.file_operations import ShellFileOperations
    except Exception:
        logger.debug("Hermes file tools not found; Windows file support not installed", exc_info=True)
        return False
    for name, native in {**_REPLACEMENTS, "search": search}.items():
        _wrap(ShellFileOperations, name, native)
    return True

"""The Hermes terminal environment that runs every command inside a Cua Space."""

from __future__ import annotations

import logging
import os
import shlex
import threading
import uuid
from typing import Any, Callable, Optional

from tools.environments.base import BaseEnvironment

from . import windows as win
from .client import ExecResult, SpaceHandle, SpacesClient
from .config import Settings, space_name_for
from .errors import CuaSpacesError, UnsupportedSpaceError

logger = logging.getLogger(__name__)

# Hermes passes its generic container default ("/root") when the user set no working folder.
_GENERIC_CWDS = ("", "/root", "~")


class _WindowsScript(str):
    """What `_wrap_command` hands `_run_bash` on a Windows Space: the command and where it runs.

    `kind` is "ps" for the terminal tool (PowerShell) and "sh" for the Unix shell commands Hermes
    builds for its other tools (Git Bash). The text itself is only a readable tag.
    """

    kind: str
    command: str
    cwd: str

    def __new__(cls, kind: str, command: str, cwd: str) -> "_WindowsScript":
        obj = super().__new__(cls, f"# hermes-cua {kind} script for a Windows Space")
        obj.kind, obj.command, obj.cwd = kind, command, cwd
        return obj


class _SpaceProcess:
    """A process-like handle for one command running in a Space.

    Hermes reads `stdout` until it closes and polls `returncode`, so we run the blocking Cua call on a
    thread, write its output into a pipe and close the pipe when the command ends.
    """

    def __init__(self, work: Callable[[], tuple[str, int]], cancel: Callable[[], None]) -> None:
        self._cancel = cancel
        self._done = threading.Event()
        self._returncode: Optional[int] = None
        read_fd, write_fd = os.pipe()
        self._writer = os.fdopen(write_fd, "wb")
        self.stdout = os.fdopen(read_fd, "r", encoding="utf-8-sig", errors="replace")
        threading.Thread(target=self._run, args=(work,), name="hermes-cua-command", daemon=True).start()

    def _run(self, work: Callable[[], tuple[str, int]]) -> None:
        try:
            output, code = work()
            self._returncode = code
            self._writer.write(output.encode("utf-8", errors="replace"))
        except Exception:
            logger.debug("command in Space failed", exc_info=True)
            if self._returncode is None:
                self._returncode = 1
        finally:
            try:
                self._writer.close()
            except OSError:
                pass
            self._done.set()

    @property
    def returncode(self) -> Optional[int]:
        return self._returncode

    def poll(self) -> Optional[int]:
        return self._returncode if self._done.is_set() else None

    def kill(self) -> None:
        try:
            self._cancel()
        except Exception:
            logger.debug("cancel failed", exc_info=True)

    def wait(self, timeout: Optional[float] = None) -> Optional[int]:
        self._done.wait(timeout=timeout)
        return self._returncode


class CuaSpaceEnvironment(BaseEnvironment):
    """Runs each Hermes command as `bash -c` inside a Cua Space.

    Terminal, file and code tools all go through `execute()`, so they all land in the Space.

    On a Windows Space the terminal tool runs in PowerShell, file read/write/patch run natively,
    and Hermes's Unix-shell tools run in Git Bash when the Space has it. See `windows.py`.
    """

    # Input for a command is staged as a file in the Space (see _run_bash), not embedded in the command.
    _stdin_mode = "payload"
    _snapshot_timeout = 60

    def __init__(
        self,
        *,
        cwd: str,
        timeout: int,
        task_id: str = "default",
        settings: Settings,
        client: SpacesClient,
        persistent: bool = True,
        **_unused: Any,
    ) -> None:
        self._settings = settings
        self._client = client
        self._persistent = persistent
        self._lock = threading.Lock()
        self._closed = False

        if settings.creates:
            # Spaces we will delete get a unique name, so parallel Hermes runs never share one.
            deleting = settings.delete_on_exit or not persistent
            self._space, created = client.ensure(space_name_for(task_id, unique=deleting), settings)
            self._delete_on_cleanup = deleting
            logger.info("Cua Space %s %s", self._space.name, "created" if created else "reused")
        else:
            self._space = client.attach(settings.space)
            self._delete_on_cleanup = False  # a Space you named is yours: never delete it

        self._win: Optional[win.WindowsInfo] = None
        self._thread_state = threading.local()
        if getattr(self._space, "os", "") == "windows":
            self._win = self._probe_windows()
            self._windows_files = None
            if cwd in _GENERIC_CWDS or not win.looks_like_windows_path(cwd):
                cwd = self._win.home  # the user profile folder
        elif cwd in _GENERIC_CWDS:
            cwd = self._space.home()
        super().__init__(cwd=cwd, timeout=timeout)
        if self._win is None:
            self.init_session()

    # -- Windows Spaces --
    @property
    def is_windows(self) -> bool:
        return self._win is not None

    @property
    def windows_info(self) -> Optional[win.WindowsInfo]:
        return self._win

    @property
    def windows_files(self):
        """Native file read/write for a Windows Space (None on Linux and macOS)."""
        if self._win is None:
            return None
        if self._windows_files is None:
            from .windows_files import WindowsFiles

            self._windows_files = WindowsFiles(self)
        return self._windows_files

    def get_temp_dir(self) -> str:
        win_info = getattr(self, "_win", None)
        return win_info.temp if win_info is not None else super().get_temp_dir()

    def _probe_windows(self) -> win.WindowsInfo:
        try:
            result = self._call(lambda sp: sp.run(win.probe_line(), 90))
        except CuaSpacesError:
            raise
        info = win.parse_probe(result.output) if result.exit_code == 0 else None
        if info is None:
            raise UnsupportedSpaceError(
                f"Could not start PowerShell in the Windows Space '{self._space.name}'. Hermes runs its "
                "commands there with PowerShell. Check that the Space is running (`cua spaces ls`) and "
                "that `powershell.exe` works in it."
            )
        logger.info(
            "Windows Space %s: shell=%s, git bash=%s", self._space.name, info.shell, info.bash or "none"
        )
        return info

    def run_powershell(self, script: str, timeout: int = 120) -> ExecResult:
        """Run a PowerShell script in the Windows Space and return its output and exit code.

        For the plugin's own file operations. The script should print only ASCII (for example base64).
        """
        info = self._win
        assert info is not None
        path = win.script_path(info, uuid.uuid4().hex[:16], "ps1")
        text = (
            f"try {{\n{script}\n}} finally {{\n"
            "  Remove-Item -LiteralPath $PSCommandPath -Force -ErrorAction SilentlyContinue\n}\n"
        )
        self._call(lambda sp: sp.write(path, text.encode("utf-8-sig")))
        return self._call(lambda sp: sp.run(win.powershell_line(info, path), timeout))

    def execute(self, command: str, cwd: str = "", *, bounded_capture: bool = False, **kwargs: Any) -> dict:
        if self._win is not None:
            # Only the foreground terminal tool sets bounded_capture. It is the one caller that sends
            # a command a person or model wrote for this machine, so it goes to PowerShell. The rest
            # are Unix shell commands Hermes built itself. Hermes's bash-only rewrite of `A && B &` must
            # not touch PowerShell.
            self._thread_state.foreground = bool(bounded_capture)
            if bounded_capture:
                kwargs["rewrite_compound_background"] = False
        return super().execute(command, cwd, bounded_capture=bounded_capture, **kwargs)

    def _wrap_command(self, command: str, cwd: str) -> str:
        if self._win is None:
            return super()._wrap_command(command, cwd)
        kind = "ps" if getattr(self._thread_state, "foreground", False) else "sh"
        return _WindowsScript(kind, command, cwd)

    # -- identity (used in messages and by the README's "watch it live" step) --
    @property
    def space_name(self) -> str:
        return self._space.name

    @property
    def space_id(self) -> str:
        return self._space.id

    # -- running commands --
    def _run_bash(
        self, cmd_string: str, *, login: bool = False, timeout: int = 120, stdin_data: Optional[str] = None
    ) -> _SpaceProcess:
        if isinstance(cmd_string, _WindowsScript):
            return self._run_windows(cmd_string, timeout=timeout, stdin_data=stdin_data)
        run_id = uuid.uuid4().hex[:16]
        script = f": hermes-cua-run-{run_id}\n{cmd_string}"
        staged: Optional[str] = None
        if stdin_data is not None:
            staged = self._staged_stdin_path()
        shell = "bash -l -c" if login else "bash -c"

        def exec_fn() -> tuple[str, int]:
            body = script
            if staged is not None:
                self._call(lambda sp: sp.write(staged, (stdin_data or "").encode("utf-8", "surrogateescape")))
                body = f": hermes-cua-run-{run_id}\n" + self._redirect_stdin_from_file(cmd_string, staged)
            line = f"exec {shell} {shlex.quote(body)} 2>&1"
            try:
                result: ExecResult = self._call(lambda sp: sp.run(line, timeout))
            except CuaSpacesError as exc:
                return (f"[Cua Space error: {exc}]\n", 1)
            return (result.output, result.exit_code)

        def cancel() -> None:
            # Best effort: stop the command's process tree. The Space has no per-command cancel.
            pattern = shlex.quote(f"[h]ermes-cua-run-{run_id}")
            kill = (
                f"for p in $(pgrep -f {pattern}); do pkill -TERM -P $p; kill -TERM $p; done; "
                f"sleep 1; for p in $(pgrep -f {pattern}); do pkill -KILL -P $p; kill -KILL $p; done; true"
            )
            try:
                self._space.run(kill, 20)
            except Exception:
                logger.debug("could not stop command %s in the Space", run_id, exc_info=True)

        return _SpaceProcess(exec_fn, cancel)

    def _run_windows(self, script: _WindowsScript, *, timeout: int, stdin_data: Optional[str]) -> _SpaceProcess:
        info = self._win
        assert info is not None
        run_id = uuid.uuid4().hex[:16]

        def stage(path: str, text: str, *, bom: bool = False) -> None:
            data = text.encode("utf-8-sig" if bom else "utf-8", "surrogateescape")
            self._call(lambda sp: sp.write(path, data))

        def exec_fn() -> tuple[str, int]:
            try:
                if script.kind == "ps":
                    staged_in = ""
                    if stdin_data is not None:
                        staged_in = self._staged_stdin_path()
                        stage(staged_in, stdin_data)
                    ps_path = win.script_path(info, run_id, "ps1")
                    stage(ps_path, win.build_powershell_script(script.command, script.cwd, self._cwd_marker, staged_in), bom=True)
                    line = win.powershell_line(info, ps_path)
                else:
                    if not info.bash:
                        return (win.NO_BASH_MESSAGE + "\n", 127)
                    command = script.command
                    if stdin_data is not None:
                        staged_in = self._staged_stdin_path()
                        stage(staged_in, stdin_data)
                        command = self._redirect_stdin_from_file(command, staged_in)
                    sh_path = win.script_path(info, run_id, "sh")
                    ps_path = win.script_path(info, run_id, "ps1")
                    stage(sh_path, win.build_bash_script(command, script.cwd, self._cwd_marker))
                    stage(ps_path, win.build_bash_launcher(info, sh_path), bom=True)
                    line = win.powershell_line(info, ps_path)
                result: ExecResult = self._call(lambda sp: sp.run(line, timeout))
            except CuaSpacesError as exc:
                return (f"[Cua Space error: {exc}]\n", 1)
            return (result.output, result.exit_code)

        def cancel() -> None:
            try:
                self._space.run(win.cancel_line(info, run_id), 30)
            except Exception:
                logger.debug("could not stop command %s in the Space", run_id, exc_info=True)

        return _SpaceProcess(exec_fn, cancel)

    def _call(self, fn):
        """Run `fn(space)`; if the connection dropped, reconnect once and retry."""
        try:
            return fn(self._space)
        except CuaSpacesError:
            with self._lock:
                try:
                    self._space = self._client.attach(self._space.id)
                except CuaSpacesError:
                    raise
            return fn(self._space)

    # -- cleanup --
    def cleanup(self) -> None:
        with self._lock:
            if self._closed or getattr(self, "_space", None) is None:
                return
            self._closed = True
            if not self._delete_on_cleanup:
                logger.info("Leaving Cua Space %s running", self._space.name)
                return
            try:
                self._client.delete(self._space.id)
                logger.info("Deleted Cua Space %s", self._space.name)
            except Exception as exc:
                self._closed = False  # let a later cleanup try again
                logger.warning(
                    "Could not delete Cua Space %s: %s. Delete it with `cua spaces delete %s`.",
                    self._space.name, exc, self._space.name,
                )
